const PRIOR_WEIGHTS = { skills: 25, title: 20, experience: 12, cv: 13, edge: 9, seniority: 10, education: 4, pay: 5, freshness: 2 };

// Weighted mean over the metrics that have evidence; missing evidence neither helps nor hurts.
